package com.smartseating.ui;

import com.smartseating.dao.DashboardDAO;
import com.smartseating.dao.ExamDAO;
import com.smartseating.model.User;
import com.smartseating.util.UI;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.function.Supplier;

public class DashboardFrame extends JFrame {
    private final User user; private final JPanel main=new JPanel(new BorderLayout(18,18));
    public DashboardFrame(User user){super("Smart Exam Seating | Dashboard");this.user=user;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1280,800);setLocationRelativeTo(null);build();}
    private void build(){main.setBackground(UI.PALE);setContentPane(main);main.add(sidebar(),BorderLayout.WEST);main.add(home(),BorderLayout.CENTER);}
    private JPanel sidebar(){JPanel nav=new JPanel();nav.setPreferredSize(new Dimension(230,0));nav.setBackground(UI.NAVY);nav.setBorder(new EmptyBorder(22,14,16,14));nav.setLayout(new BoxLayout(nav,BoxLayout.Y_AXIS));JLabel logo=new JLabel("▦  SMART SEATING");logo.setForeground(Color.WHITE);logo.setFont(new Font("SansSerif",Font.BOLD,16));nav.add(logo);JLabel role=new JLabel("  "+user.getFullName()+" • "+user.getRole());role.setForeground(new Color(170,199,226));role.setBorder(new EmptyBorder(8,0,18,0));nav.add(role);String[][] items={{"DASHBOARD",""},{"STUDENTS","STUDENT"},{"DEPARTMENTS","DEPARTMENT"},{"SEMESTERS","SEMESTER"},{"ROOMS","ROOM"},{"QUICK ROOM SETUP","QUICK"},{"ROOM TEMPLATES","TEMPLATE"},{"TEACHERS","TEACHER"},{"USERS","USER"},{"EXAMS","EXAM"},{"GENERATE SEATING","GENERATE"},{"SEARCH SEAT","SEARCH"},{"SEATING REPORT","REPORT"},{"ATTENDANCE","ATTENDANCE"},{"INVIGILATOR DUTY","DUTY"},{"CAPACITY REPORT","CAPACITY"},{"PRINT REPORTS","REPORT"},{"SETTINGS","SETTINGS"}};for(String[] item:items){if(("USER".equals(item[1])||"QUICK".equals(item[1])||"TEMPLATE".equals(item[1]))&&!("ADMIN".equals(user.getRole())))continue;JButton b=new JButton("  "+item[0]);b.setHorizontalAlignment(SwingConstants.LEFT);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,37));b.setForeground(Color.WHITE);b.setBackground(item[0].equals("DASHBOARD")?UI.BLUE:UI.NAVY);b.setBorder(new EmptyBorder(8,8,8,4));b.setFocusPainted(false);b.addActionListener(e->navigate(item[1]));nav.add(b);}nav.add(Box.createVerticalGlue());JButton logout=new JButton("  LOGOUT");logout.setHorizontalAlignment(SwingConstants.LEFT);logout.setForeground(new Color(255,213,150));logout.setBackground(UI.NAVY);logout.setBorder(new EmptyBorder(12,8,12,4));logout.addActionListener(e->{new LoginFrame().setVisible(true);dispose();});nav.add(logout);return nav;}
    private JPanel home(){JPanel p=new JPanel(new BorderLayout(0,18));p.setBorder(new EmptyBorder(22,4,22,22));p.setBackground(UI.PALE);JPanel header=new JPanel(new BorderLayout());header.setOpaque(false);JLabel h=new JLabel("Examination control centre");h.setFont(new Font("SansSerif",Font.BOLD,27));h.setForeground(UI.INK);JLabel hi=new JLabel("Plan, generate and print every seat from one place");hi.setForeground(UI.MUTED);header.add(h,BorderLayout.NORTH);header.add(hi,BorderLayout.SOUTH);p.add(header,BorderLayout.NORTH);JPanel cards=new JPanel(new GridLayout(2,3,14,14));cards.setOpaque(false);String[] names={"Total Students","Departments","Teachers","Rooms","Room Capacity","Upcoming Exams"};String[] keys={"students","departments","teachers","rooms","capacity","exams"};for(int i=0;i<names.length;i++)cards.add(card(names[i],keys[i]));p.add(cards,BorderLayout.CENTER);JPanel quick=new JPanel(new FlowLayout(FlowLayout.LEFT,10,8));quick.setBackground(Color.WHITE);quick.setBorder(new EmptyBorder(10,12,10,12));JLabel q=new JLabel("Quick action");q.setFont(new Font("SansSerif",Font.BOLD,13));quick.add(q);JButton gen=UI.button("GENERATE SEATING",UI.TEAL);gen.addActionListener(e->navigate("GENERATE"));quick.add(gen);JButton search=UI.button("SEARCH STUDENT SEAT",UI.BLUE);search.addActionListener(e->navigate("SEARCH"));quick.add(search);p.add(quick,BorderLayout.SOUTH);return p;}
    private JPanel card(String label,String key){JPanel p=new JPanel(new BorderLayout());p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(224,230,238)),new EmptyBorder(16,18,16,18)));JLabel l=new JLabel(label.toUpperCase());l.setForeground(UI.MUTED);l.setFont(new Font("SansSerif",Font.BOLD,11));JLabel value=new JLabel("—");value.setFont(new Font("SansSerif",Font.BOLD,29));value.setForeground(UI.INK);p.add(l,BorderLayout.NORTH);p.add(value,BorderLayout.CENTER);try{long count=switch(key){case "capacity"->new DashboardDAO().roomCapacity();case "exams"->new ExamDAO().countUpcoming();default->new DashboardDAO().count(key);};value.setText(String.valueOf(count));}catch(Exception ex){value.setText("!");}return p;}
    private void navigate(String key){JFrame frame=switch(key){case "STUDENT"->new StudentFrame(user);case "DEPARTMENT"->new DepartmentFrame(user);case "SEMESTER"->new SemesterFrame(user);case "ROOM"->new RoomFrame(user);case "QUICK"->new QuickRoomSetupFrame(user);case "TEMPLATE"->new RoomTemplateFrame(user);case "TEACHER"->new TeacherFrame(user);case "EXAM"->new ExamFrame(user);case "GENERATE"->new GenerateSeatingFrame(user);case "SEARCH"->new StudentSeatSearchFrame(user);case "REPORT"->new ReportsFrame(user);case "ATTENDANCE"->new AttendanceFrame(user);case "DUTY"->new InvigilatorFrame(user);case "CAPACITY"->new CapacityFrame(user);default->null;};if(frame!=null){frame.setVisible(true);}}
}
